from jsonb_to_recordset($json$[{"id":"che-pe-221","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electronegativity falls in the order N > P > As because","options":["atomic size increases down group 15","nuclear charge falls down the group","they become alkali metals","the number of valence electrons decreases"],"answer_index":0,"explanation":"The bonded pair is held farther from the nucleus in the larger P and As atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-222","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In period 2 the electronegativity order is","options":["F < O < N < C","C < N < O < F","N < C < F < O","O < C < N < F"],"answer_index":1,"explanation":"χ rises steadily across the period as Zeff increases and radius falls.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-223","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine is more electronegative than chlorine, bromine and iodine because of its","options":["larger size and lower Zeff","small size and high effective nuclear charge","half-filled 3d subshell","metallic character"],"answer_index":1,"explanation":"The shared pair in an F–X bond sits closest to a compact, highly charged fluorine atom.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-224","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"On the Mulliken scale, electronegativity is taken as the average of","options":["atomic radius and density","ionisation enthalpy and electron gain enthalpy (in suitable units)","mass number and atomic number","melting point and boiling point"],"answer_index":1,"explanation":"Mulliken wrote χ ∝ (IE + EA)/2, combining the two isolated-atom energies that measure electron holding and accepting.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-225","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The H–F bond is more polar than the H–Cl bond because fluorine is","options":["less electronegative than chlorine","more electronegative than chlorine","larger than chlorine","a metal"],"answer_index":1,"explanation":"The greater χ(F) − χ(H) gap displaces the shared pair more strongly toward fluorine.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-226","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine outranks chlorine in electronegativity even though Cl has more protons, because the bonding pair in an F–X bond is","options":["farther from the F nucleus","much closer to the small, poorly shielded fluorine atom","held only by London forces","shared equally in every case"],"answer_index":1,"explanation":"Size and Zeff on the valence shell dominate χ; the extra protons of Cl are offset by an extra shielding shell.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"electronegativity","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-227","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Valence electrons of an atom are those present in its","options":["innermost shell","outermost shell","nucleus","neutron cloud"],"answer_index":1,"explanation":"Chemical valence is decided by the electrons in the highest principal shell.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-228","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Alkali metals exhibit a characteristic valence of","options":["one","two","three","seven"],"answer_index":0,"explanation":"Each atom has a single ns¹ electron, which it loses (or shares) in compounds.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-229","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Halogens commonly exhibit a valence of one, corresponding to the oxidation state","options":["+7 in every ionic salt","−1 in simple ionic compounds","+1 only","zero in all molecules"],"answer_index":1,"explanation":"Gain of one electron completes the octet and gives X⁻ (fluoride, chloride, …).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-230","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The characteristic oxidation state of alkali metals in their compounds is","options":["−1","+1","+2","+7"],"answer_index":1,"explanation":"Loss of the single valence electron leaves a noble-gas cation M⁺.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-231","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"For many p-block elements the highest oxidation state equals the","options":["number of neutrons","number of valence electrons (the old group number)","period number","mass number minus Z"],"answer_index":1,"explanation":"Group 15 can reach +5, group 16 +6 and group 17 +7 when all valence electrons are involved.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-232","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Carbon is tetravalent in the great majority of its stable compounds because it has","options":["two valence electrons","four valence electrons","six valence electrons","no valence electrons"],"answer_index":1,"explanation":"The 2s² 2p² set provides four electrons for four covalent bonds (as in CH₄).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"valence-ox-states","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
